 49	  // Cached dispatch and `~middleware` composition (invalidated by `use()` and `mount()`)
 50	  "~dispatch"?: (event: H3Event, route: MatchedRoute<H3Route> | void) => unknown | Promise<unknown>;
 51	  "~composed"?: ComposedMiddleware;
