154	      config.plugins?.forEach((plugin) => plugin(this as unknown as H3Type));
155	    }
156	
157	    register(plugin: H3Plugin) {
158	      plugin(this as unknown as H3Type);
159	      return this;
160	    }
161	
162	    request(
