166	    ): Response | Promise<Response> {
167	      return this["~request"](toRequest(_req, _init), context);
168	    }
169	
170	    mount(base: string, input: FetchHandler | FetchableObject | H3Type) {
171	      // Same normalization the mounted routes get from `on()`, minus the
172	      // trailing slash: a base is a prefix, not a route.
173	      base = !base || base === "/" ? "" : normalizeRoute(base).replace(/\/$/, "");
174	      if ("handler" in input) {
175	        if (input["~middleware"].length > 0) {
176	          this["~middleware"].push((event, next) => {
177	            const originalPathname = event.url.pathname;
178	            if (
179	              !originalPathname.startsWith(base) ||
180	              (originalPathname.length > base.length && originalPathname[base.length] !== "/")
181	            ) {
182	              return next();
183	            }
184	            // Not `next()`: skipping the mounted middleware would still let the
185	            // mounted `/**` routes serve the request without it.
186	            if (hasEmptySegmentAfterBase(originalPathname, base)) {
187	              throw new HTTPError({ status: 404 });
188	            }
189	            event.url.pathname = stripBase(originalPathname, base);
190	            const restore = () => {
191	              event.url.pathname = originalPathname;
192	            };
193	            try {
194	              // Shares the mounted app's own cache (invalidated by its `use()`)
195	              const composed = (input["~composed"] ??= composeMiddleware(input["~middleware"]));
196	              const result = composed(event, () => {
197	                restore();
198	                return next();
199	              });
200	              if (typeof (result as PromiseLike<unknown>)?.then === "function") {
201	                // Promise.resolve normalizes bare thenables that lack .finally
202	                return Promise.resolve(result).finally(restore);
203	              }
204	              restore();
205	              return result;
206	            } catch (err) {
207	              restore();
208	              throw err;
209	            }
210	          });
211	          this["~dispatch"] = this["~composed"] = undefined;
212	        }
213	        for (const r of input["~routes"]) {
214	          this["~addRoute"]({
215	            ...r,
216	            route: base + r.route,
217	          });
218	        }
219	      } else {
220	        const fetchHandler = "fetch" in input ? input.fetch : input;
221	        this.all(`${base}/**`, function _mountedMiddleware(event) {
222	          if (hasEmptySegmentAfterBase(event.url.pathname, base)) {
223	            throw new HTTPError({ status: 404 });
224	          }
225	          return fetchHandler(requestWithBaseURL(event.req, base, { url: event.url }));
226	        });
227	      }
228	      return this;
229	    }
230	
231	    on(
232	      method: HTTPMethod | Lowercase<HTTPMethod> | "",
233	      route: string,
234	      handler: HTTPHandler,
235	      opts?: RouteOptions,
236	    ): this {
237	      const _method = (method || "").toUpperCase();
238	      route = normalizeRoute(route);
239	      this["~addRoute"]({
240	        method: _method as HTTPMethod,
241	        route,
242	        handler: toEventHandler(handler)!,
243	        middleware: opts?.middleware,
244	        meta: { ...(handler as EventHandler).meta, ...opts?.meta },
245	      });
246	      return this;
247	    }
248	
249	    all(route: string, handler: HTTPHandler, opts?: RouteOptions) {
250	      return this.on("", route, handler, opts);
251	    }
252	
253	    override "~findRoute"(_event: H3Event): MatchedRoute<H3Route> | void {
254	      const match = findRoute<H3Route>(this["~rou3"], _event.req.method, _event.url.pathname);
255	      if (match === undefined && _event.req.method === "HEAD") {
