268	    use(arg1: unknown, arg2?: unknown, arg3?: unknown): this {
269	      let route: string | undefined;
270	      let fn: Middleware | H3Type;
271	      let opts: MiddlewareOptions | undefined;
272	      if (typeof arg1 === "string") {
273	        route = arg1;
274	        fn = arg2 as Middleware | H3Type;
275	        opts = arg3 as MiddlewareOptions;
276	      } else {
277	        fn = arg1 as Middleware | H3Type;
278	        opts = arg2 as MiddlewareOptions;
279	      }
280	      if (typeof fn !== "function" && "handler" in (fn as object)) {
