286	    }
287	  }
288	
289	  // prettier-ignore
290	  for (const method of ["GET", "POST", "PUT", "DELETE", "PATCH", "HEAD", "OPTIONS", "CONNECT", "TRACE", "QUERY"] as const) {
291	    (H3Core as any).prototype[method.toLowerCase()] = function (
292	      this: H3Type,
293	      route: string,
294	      handler: HTTPHandler,
295	      opts?: RouteOptions,
296	    ) {
297	      return this.on(method, route, handler, opts);
298	    };
299	  }
300	
301	  return H3;
302	})() as unknown as { new (config?: H3Config): H3Type };
303	
304	export type H3 = H3Type;

